input.content:
workspace "Energy Manager" "C4 model of the home energy management platform" {

    model {

        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs."

        energyManager = system "Energy Manager" "Home energy management platform owned and operated by our company." {

            dashboard = softwareComponent "Dashboard Web App" "Web app where homeowners see consumption and costs."

            scheduler = softwareComponent "Scheduling Service" "Service that plans charging and heating."

            ratesLibrary = softwareComponent "Rates Library" "Shared library that computes energy prices from tariff and time of day."

            database = systemDatabase "Energy Manager Database" "Database that stores meter readings and schedules. Operated by our company."
        }

        smartMeterProvider = system "Smart Meter Provider" "External smart meter provider that supplies live meter readings. Operated by a different organization."

        homeowner -> dashboard "Manages household energy use and costs"
        dashboard -> ratesLibrary "Embeds"
        scheduler -> ratesLibrary "Embeds"
        scheduler -> smartMeterProvider "Fetches live meter readings"
        scheduler -> database "Stores meter readings and schedules"
    }

    views {

        systemContext energyManager "SystemContext" "System context diagram for the Energy Manager." {
            include *
            autoLayout
        }

        container energyManager "Containers" "Container diagram for the Energy Manager." {
            include *
            autoLayout
        }

        component dashboard "DashboardComponents" "Component diagram for the Dashboard Web App." {
            include *
            autoLayout
        }

        component scheduler "SchedulerComponents" "Component diagram for the Scheduling Service." {
            include *
            autoLayout
        }
    }
}

